"""Export state_script and parse_state reference data, generated by the Python implementation."""

import json
import sys
import tempfile
from pathlib import Path

# scripts/fixtures/secrets.py would otherwise shadow the stdlib module httpx imports.
sys.path = [entry for entry in sys.path if Path(entry).resolve() != Path(__file__).parent]

from ffpr_agent import laptop as lp  # noqa: E402 (after the sys.path fix above)
from ffpr_agent import view  # noqa: E402

ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT / "test" / "fixtures" / "state-script.json"
PROBE = ROOT.parent / ".deps" / "ff5" / "probe" / "probe-20261020-014347.jsonl"

laptop = lp.Laptop(
    host="192.168.8.230",
    user="ffpr",
    key=Path("/home/dev/.ssh/ffpr_laptop_ed25519"),
    root="C:/ffpr",
)

text = PROBE.read_text(encoding="utf-8")
tail = PROBE.read_bytes()[-view.TAIL_BYTES :].decode("utf-8", errors="replace")
state_text = f"{PROBE.name}\n{tail}"

records = view.parse_tail(state_text)
last_seq = records[-1]["seq"]
cursor_seq = max(0, last_seq - 8)

with tempfile.TemporaryDirectory() as directory:
    cursor = Path(directory) / "state-cursor.json"
    original = view.CURSOR
    view.CURSOR = cursor
    try:
        cursor.write_text(json.dumps({"file": PROBE.name, "seq": cursor_seq}), encoding="utf-8")
        sample, events = view.parse_state(state_text)
        seeded = {"sample": sample, "events": events, "cursor": cursor.read_text()}

        small = (
            "probe-small.jsonl\n"
            '{"seq":1,"type":"hello"},garbage\n'
            '{"seq":2,"type":"sample","scene":{"name":"Field"}}\n'
            '{"seq":3,"type":"sysmsg","text":"消息"}\n'
            '{"seq":4,"type":"dialog.close"}\n'
            '{"seq":5,"type":"sample","scene":{"name":"Next"}}\n'
        )
        cursor.write_text(json.dumps({"file": "old.jsonl", "seq": 99}), encoding="utf-8")
        sample2, events2 = view.parse_state(small)
        empty = {
            "sample": sample2,
            "events": events2,
            "cursor": json.loads(cursor.read_text()),
        }
    finally:
        view.CURSOR = original

out = {
    "state_script": view.state_script(laptop, "FF5"),
    "tail_bytes": view.TAIL_BYTES,
    "file": PROBE.name,
    "cursor_seq": cursor_seq,
    "input": state_text,
    "seeded": seeded,
    "empty_cursor": {**empty, "input": small},
}

OUT.write_text(json.dumps(out, ensure_ascii=False, indent=1) + "\n", encoding="utf-8")
print(f"wrote {OUT}")
